SELECT 
    RTRIM(
        CAST(
            CONVERT(
                VARCHAR(50),
                DATEADD(
                    SECOND,
                    DATEDIFF(SECOND, GETDATE(), GETUTCDATE()),
                    '08/26/2014 08:18:00'
                ),
                127
            ) AS VARCHAR
        )
    ) + 'Z' AS ISO_Date;
